let src=fs.readFileSync(path.join(root,'assets/app.js'),'utf8').replace('  boot();',`  window.__t={choose:code=>{S=fresh();S.branch=D.branchByCode[code];S.scope=(S.branch.lat==null||S.branch.lon==null)&&sectorCity(S.branch.city)?'city':'branch';},selectCity,renderStart,renderSection,filterQuery,visibleItemsFor,cityKey,selectBranch,itemsFor,rawItems,unlocatedItemsFor,nearestBranch,employeeGreeting,cities,sameCity,radiusApplies,compute,displayEligible,card,renderBranch,setScope:(x,r)=>{S.scope=x;S.radius=r||15;},data:()=>D,state:()=>S}; boot();`);
vm.runInNewContext(src,{document,window,location,history:{replaceState(){}},localStorage,navigator:{},fetch,setTimeout,clearTimeout,console,URL,Blob});
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{await sleep(1500);const A=window.__t,D=A.data(),assert=require('assert');
A.renderStart();els['q-branch'].value='الدمام';els['q-branch'].handlers.input();
let expected=D.branches.filter(b=>A.state() && b.n.includes('الدمام'));assert(expected.length>0);assert(!els['branch-list'].innerHTML.includes('data-code="322"'));assert(!els['branch-list'].innerHTML.includes('data-code="303"'));
const results={};
A.selectBranch('243',true);A.state().tab='nhc';
for(const sec of ['شرق','شمال','جنوب','غرب','وسط']){A.state().scope='sector';A.state().explore=sec;A.state().nhcView='local';let c=A.compute().nhc;assert(c.items.length>0,sec);assert(c.local.every(x=>x.o.sectors.includes(sec)));assert(c.nearby.every(x=>!x.o.sectors.includes(sec)));assert(c.nearby.every((x,i,a)=>!i||x.d>=a[i-1].d));assert(c.local.length||c.fallback);results[sec]={primary:c.local.map(x=>x.o.n),shown:c.items.map(x=>x.o.n),nearby:c.nearby.map(x=>x.o.n),fallback:c.fallback};A.state().nhcView='nearby';let near=A.compute().nhc;assert.strictEqual(near.items.length,c.nearby.length);A.renderBranch();assert(els.content.innerHTML.includes('وجهات أخرى قريبة من النطاق'));}
A.selectBranch('311',true);let th=A.compute();let kh=D.branches.find(b=>b.city==='الخبر');A.selectBranch(kh.c,true);let khc=A.compute();for(const k of ['projects','opps','nhc','companies'])assert.deepStrictEqual(th[k].items.map(x=>x.o.id||x.o.n).sort(),khc[k].items.map(x=>x.o.id||x.o.n).sort());assert(th.projects.items.length>0);results.thuqbah=Object.fromEntries(['projects','opps','nhc','companies'].map(k=>[k,th[k].items.length]));for(const city of ['الظهران','الدرعية','سيهات','القطيف','أم الحمام']){const b=D.branches.find(x=>x.city===city);A.selectBranch(b.c,true);A.state().tab='nhc';A.renderBranch();const c=A.compute().nhc;assert(c.items.length>0,city+' documented nearby fallback');assert(c.items.every(x=>x.d!=null&&x.o.city!==city));assert(!els.app.innerHTML.includes('من 0'));assert(els.content.innerHTML.includes('خارج المدينة'));results[city]=c.items.map(x=>({name:x.o.n,city:x.o.city,d:x.d}));}
A.selectBranch('243',true);A.state().tab='projects';A.state().scope='unassigned';let unknown=A.compute().projects.items;assert(unknown.length>0);assert(unknown.every(x=>!(x.o.sectors&&x.o.sectors.length)&&!x.o.sec));A.renderBranch();assert(els.content.innerHTML.includes('دون قطاع مسجّل'));results.unknownApprovedRiyadh=unknown.length;
A.selectBranch('307',true);let missing=A.compute().nhc;assert(!missing.fallback,'No nearest assertion without branch pin');
assert(A.card('offices',{id:'QA-SEARCH',n:'اختبار',city:'الرياض',maps:'https://www.google.com/maps?q=مكتب+اختبار'}).includes('بحث في الخرائط'));
assert(!A.card('offices',{id:'QA-POINT',n:'اختبار',city:'الرياض',maps:'https://www.google.com/maps?q=24.7,46.7'}).includes('بحث في الخرائط'));
console.log(JSON.stringify(results,null,2));})().catch(e=>{console.error(e.stack);process.exitCode=1});
